package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTimeoutPreemptively;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.backup.BackupCompression;
import org.eclipse.rdf4j.sail.backup.BackupRequest;
import org.eclipse.rdf4j.sail.backup.BackupResult;
import org.eclipse.rdf4j.sail.backup.BackupType;
import org.eclipse.rdf4j.sail.backup.PointInTimeRestoreRequest;
import org.eclipse.rdf4j.sail.backup.SailBackupService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbBackupRecoveryTest {

	@Test
	void emptyFullSnapshotPreservesLogicalBoundaryAfterRestore(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("store").toFile());
		store.init();
		try {
			Path backup = directory.resolve("backup");
			SailBackupService service = store.getBackupService();
			BackupResult full = full(service, backup);
			Path restored = service.restore(new PointInTimeRestoreRequest(backup, directory.resolve("restore"),
					full.getEndTransactionId(), true));
			LmdbStore restoredStore = new LmdbStore(restored.toFile());
			restoredStore.init();
			try {
				assertEquals(full.getEndTransactionId(), restoredStore.getBackingStore().getCurrentCommittedTxnId());
				add(restoredStore, "after-empty-full");
				assertEquals(full.getEndTransactionId() + 1,
						restoredStore.getBackingStore().getCurrentCommittedTxnId());
			} finally {
				restoredStore.shutDown();
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void failedPublicationSurvivesReopenUntilCoveredByFullSnapshot(@TempDir Path directory) throws Exception {
		Path data = directory.resolve("store");
		Path backup = directory.resolve("backup");
		LmdbStore store = new LmdbStore(data.toFile());
		BackupResult originalFull;
		store.init();
		try {
			add(store, "seed");
			SailBackupService service = store.getBackupService();
			originalFull = full(service, backup);
			long missing = store.getBackingStore().getCurrentCommittedTxnId() + 1;
			Path obstructed = backup.resolve("txlog").resolve(logName(missing));
			Files.createDirectories(obstructed.getParent());
			Files.createDirectory(obstructed);
			add(store, "failed");
			assertEquals("commit-delta", service.getStatus().getLastFailureStage().orElseThrow());
			assertTimeoutPreemptively(Duration.ofSeconds(5),
					() -> assertThrows(SailException.class,
							() -> incremental(service, backup, originalFull.getEndTransactionId())));
			Files.delete(obstructed);
		} finally {
			store.shutDown();
		}

		store = new LmdbStore(data.toFile());
		store.init();
		try {
			SailBackupService service = store.getBackupService();
			assertTimeoutPreemptively(Duration.ofSeconds(5),
					() -> assertThrows(SailException.class,
							() -> incremental(service, backup, originalFull.getEndTransactionId())));
			add(store, "later");
			assertThrows(SailException.class,
					() -> incremental(service, backup, originalFull.getEndTransactionId()));
			BackupResult recoveredFull = full(service, backup);
			add(store, "after-full");
			BackupResult recovered = incremental(service, backup, recoveredFull.getEndTransactionId());
			Path restored = service.restore(new PointInTimeRestoreRequest(backup, directory.resolve("restore"),
					recovered.getEndTransactionId(), true));
			LmdbStore restoredStore = new LmdbStore(restored.toFile());
			restoredStore.init();
			try {
				assertPresent(restoredStore, "failed");
				assertPresent(restoredStore, "later");
				assertPresent(restoredStore, "after-full");
			} finally {
				restoredStore.shutDown();
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void restoreFiltersIncrementalOverlappingNewerFullSnapshot(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("store").toFile());
		store.init();
		try {
			Path backup = directory.resolve("backup");
			SailBackupService service = store.getBackupService();
			add(store, "seed");
			BackupResult originalFull = full(service, backup);
			add(store, "a");
			full(service, backup);
			add(store, "b");
			BackupResult overlapping = incremental(service, backup, originalFull.getEndTransactionId());
			try (var logs = Files.list(backup.resolve("txlog"))) {
				for (Path log : logs.toList()) {
					Files.delete(log);
				}
			}
			Path restored = service.restore(new PointInTimeRestoreRequest(backup, directory.resolve("restore"),
					overlapping.getEndTransactionId(), true));
			LmdbStore restoredStore = new LmdbStore(restored.toFile());
			restoredStore.init();
			try {
				assertPresent(restoredStore, "a");
				assertPresent(restoredStore, "b");
				assertEquals(overlapping.getEndTransactionId(),
						restoredStore.getBackingStore().getCurrentCommittedTxnId());
			} finally {
				restoredStore.shutDown();
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void restoreRejectsInteriorGapWithoutChecksumVerification(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("store").toFile());
		store.init();
		try {
			Path backup = directory.resolve("backup");
			SailBackupService service = store.getBackupService();
			add(store, "seed");
			BackupResult full = full(service, backup);
			add(store, "a");
			long missing = store.getBackingStore().getCurrentCommittedTxnId();
			add(store, "b");
			BackupResult incremental = service.createBackup(BackupRequest.builder(backup, BackupType.INCREMENTAL)
					.sinceTransactionId(full.getEndTransactionId())
					.compression(BackupCompression.NONE)
					.build());
			Files.delete(incremental.getArtifactPath().resolve(logName(missing)));
			Files.delete(backup.resolve("txlog").resolve(logName(missing)));
			SailException failure = assertThrows(SailException.class,
					() -> service.restore(new PointInTimeRestoreRequest(backup, directory.resolve("restore"),
							incremental.getEndTransactionId(), false)));
			assertTrue(failure.getMessage().contains("gap"), failure.getMessage());
		} finally {
			store.shutDown();
		}
	}

	private static void add(LmdbStore store, String subject) {
		var vf = SimpleValueFactory.getInstance();
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(vf.createIRI("urn:" + subject), vf.createIRI("urn:p"), vf.createLiteral("value"));
			connection.commit();
		}
	}

	private static void assertPresent(LmdbStore store, String subject) {
		try (var connection = store.getConnection()) {
			assertTrue(connection.hasStatement(SimpleValueFactory.getInstance().createIRI("urn:" + subject),
					null, null, false));
		}
	}

	private static BackupResult full(SailBackupService service, Path directory) {
		return service.createBackup(BackupRequest.builder(directory, BackupType.FULL)
				.compression(BackupCompression.ZIP)
				.build());
	}

	private static BackupResult incremental(SailBackupService service, Path directory, long since) {
		return service.createBackup(BackupRequest.builder(directory, BackupType.INCREMENTAL)
				.sinceTransactionId(since)
				.compression(BackupCompression.ZIP)
				.build());
	}

	private static String logName(long transaction) {
		return String.format("txn-%020d.delta.gz", transaction);
	}
}
